begin;reset role;select set_config('qa.payload_expires',(clock_timestamp()+interval '2 hours')::text,true);
insert into auth.users(id,email) values('11111111-66cc-4abe-a507-111111111177','qa-message-renewal@example.test');insert into profiles(id) values('11111111-66cc-4abe-a507-111111111177');insert into agent_threads(id,user_id,title) values('22222222-66cc-4abe-a507-222222221177','11111111-66cc-4abe-a507-111111111177','Synthetic same-entry renewal');insert into career_message_approval_private.test_users(user_id) values('11111111-66cc-4abe-a507-111111111177');insert into career_watch_kv(user_id,key,value) values('11111111-66cc-4abe-a507-111111111177','career:account','{"epoch":2,"version":3,"paused":false,"daily_limit":"5"}');
