create function pg_temp.qa_hash(x jsonb) returns text language sql security definer set search_path=public,pg_temp as $$select encode(sha256(convert_to(public.career_apply_canonical(x),'UTF8')),'hex')$$;
create temp table qa_renew(k text primary key,v jsonb);grant all on qa_renew to authenticated,service_role;
insert into qa_renew values('payload','{"version": 1, "source": "extension", "user_id": "11111111-66cc-4abe-a507-111111111177", "manifest_hash": "6666666666666666666666666666666666666666666666666666666666666666", "quarantine_version": "d007-v1", "job_id": "lever:synthetic:qa-message-renewal", "company": "Synthetic QA renewal", "url": "https://jobs.lever.co/synthetic/renewal/apply", "family": "lever", "fields": [{"name": "name", "label": "Full name", "value": "TEST Person", "source": "trainee", "factId": "TEST-NAME", "detail": ""}, {"name": "resume", "label": "Resume/CV", "value": "synthetic.pdf", "source": "trainee", "factId": "approved-local-resume:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", "detail": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa:12345:application/pdf"}], "resume_name": "synthetic.pdf", "resume_sha256": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", "privacy_epoch": 2, "account_version": 3}'::jsonb||jsonb_build_object('expires_at',current_setting('qa.payload_expires')));
