reset role;
insert into qa_renew select 'fresh_binding',jsonb_build_object('approval_id',approval_id) from career_message_approval_private.bound_approvals where user_id='11111111-66cc-4abe-a507-111111111177'::uuid and approval_id<>(select (v->>'approval_id')::uuid from qa_renew where k='original_binding');
do $qa$ begin update career_apply_jobs set claimed_at=clock_timestamp() where id=(select (v->>'id')::uuid from qa_renew where k='job');insert into qa_renew values('renewal_attempt','{"accepted":true}');exception when others then insert into qa_renew values('renewal_attempt',jsonb_build_object('accepted',false,'reason',SQLERRM));end $qa$;
select t.as_user('11111111-66cc-4abe-a507-111111111177');set role authenticated;
do $qa$ declare z career_apply_jobs;begin select done.* into z from qa_renew q cross join lateral career_apply_finish_own((q.v->>'id')::uuid,(q.v->>'lease')::uuid,'unknown_outcome','{"reason":"synthetic expired-permission terminal receipt"}'::jsonb) done where q.k='job';insert into qa_renew values('terminal',jsonb_build_object('accepted',true,'state',z.state));exception when others then insert into qa_renew values('terminal',jsonb_build_object('accepted',false,'reason',SQLERRM));end $qa$;
reset role;
select jsonb_build_object('original_bound_id_unchanged',(select b.approval_id=(select (v->>'approval_id')::uuid from qa_renew where k='original_binding') from career_message_approval_private.bound_jobs b where b.job_row_id=(select (v->>'id')::uuid from qa_renew where k='job')),'fresh_approval_id_differs',(select (select v->>'approval_id' from qa_renew where k='original_binding')<>(select v->>'approval_id' from qa_renew where k='fresh_binding')),'fresh_approval_remains_unused',(select used_at is null from career_apply_batch_approvals where id=(select (v->>'approval_id')::uuid from qa_renew where k='fresh_binding')),'renewal_attempt',(select v from qa_renew where k='renewal_attempt'),'terminal',(select v from qa_renew where k='terminal'),'total_jobs',(select count(*) from career_apply_jobs where user_id='11111111-66cc-4abe-a507-111111111177'::uuid));
rollback;
